      pt: ["Altitude: aprox. 800 m", "Comprimento do planalto: 20 km", "Wadi mais profundo: 300 m", "Número de aldeias: 5", "Área agrícola: 10 km²", "Espécies de plantas: >100, incluindo a prímula-árabe"],
      fr: ["Altitude : env. 800 m", "Longueur du plateau : 20 km", "Oued le plus profond : 300 m", "Nombre de villages : 5", "Surface agricole : 10 km²", "Espèces végétales : >100, dont la primevère d'Arabie"],
